import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

import BookingForm from "../components/BookingForm";
import BookingList from "../components/BookingList";
import InchargeModal from "../components/InchargeModal";
import Navbar from "../components/Navbar";
import Sidebar from "../components/Sidebar";
import api from "../services/api";

const clientNavItems = [
  { key: "overview", label: "Overview", icon: "O", to: "/" },
  { key: "new-booking", label: "New Booking", icon: "+", to: "/new-booking" },
  { key: "my-bookings", label: "My Bookings", icon: "B", to: "/my-bookings" },
  { key: "incharges", label: "Incharges", icon: "I" }
];

const pageContent = {
  overview: {
    title: "Booking Overview",
    subtitle: "Track recent requests, approvals, and rejections in one place."
  },
  "new-booking": {
    title: "New Booking",
    subtitle: "Select a block or extra center and submit a booking request."
  },
  "my-bookings": {
    title: "My Bookings",
    subtitle: "Review your requests, rejection notes, and cancellations."
  }
};

const initialFormState = {
  resourceScope: "block",
  blockId: "",
  resourceId: "",
  bookingDate: "",
  startTime: "",
  endTime: "",
  purpose: ""
};

const ClientDashboard = ({ view = "overview" }) => {
  const navigate = useNavigate();
  const [bookings, setBookings] = useState([]);
  const [inchargeGroups, setInchargeGroups] = useState([]);
  const [showIncharges, setShowIncharges] = useState(false);
  const [formData, setFormData] = useState(initialFormState);
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);

  const handleLogout = () => {
    localStorage.removeItem("token");
    navigate("/login");
  };

  const loadBookings = async () => {
    try {
      const response = await api.get("/client/bookings");
      setBookings(response.data || []);
    } catch (error) {
      setMessage(error.response?.data?.detail || "Could not load bookings.");
    }
  };

  const loadIncharges = async () => {
    try {
      const response = await api.get("/incharges");
      setInchargeGroups(response.data || []);
    } catch {
      setInchargeGroups([]);
    }
  };

  useEffect(() => {
    loadBookings();
    loadIncharges();
  }, []);

  const handleChange = (event) => {
    const { name, value } = event.target;
    setFormData((previous) => ({
      ...previous,
      [name]: value
    }));
  };

  const handleAvailabilityCheck = async () => {
    setMessage("");

    try {
      const response = await api.post("/client/availability", {
        resource_id: Number(formData.resourceId),
        booking_date: formData.bookingDate,
        start_time: formData.startTime,
        end_time: formData.endTime
      });
      setMessage(response.data.available ? "Resource is available." : "Resource is already booked.");
    } catch (error) {
      setMessage(error.response?.data?.detail || "Could not check availability.");
    }
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setLoading(true);
    setMessage("");

    try {
      await api.post("/client/bookings", {
        resource_id: Number(formData.resourceId),
        booking_date: formData.bookingDate,
        start_time: formData.startTime,
        end_time: formData.endTime,
        purpose: formData.purpose
      });

      setMessage("Booking created successfully.");
      setFormData(initialFormState);
      await loadBookings();
      navigate("/my-bookings");
    } catch (error) {
      setMessage(error.response?.data?.detail || "Booking failed.");
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = async (bookingId) => {
    const reason = window.prompt("Enter cancellation reason:");
    if (!reason) {
      return;
    }

    try {
      await api.post(`/client/bookings/${bookingId}/cancel`, { reason });
      setMessage("Booking cancelled.");
      await loadBookings();
    } catch (error) {
      setMessage(error.response?.data?.detail || "Cancellation failed.");
    }
  };

  const handleSidebarSelect = (itemKey) => {
    if (itemKey === "incharges") {
      setShowIncharges(true);
    }
  };

  const currentPage = pageContent[view] || pageContent.overview;
  const recentBookings = bookings.slice(0, 3);
  const pendingCount = bookings.filter((booking) => booking.status === "pending").length;
  const approvedCount = bookings.filter((booking) => booking.status === "approved").length;
  const rejectedCount = bookings.filter((booking) => booking.status === "rejected").length;

  return (
    <div className="dashboard-shell">
      <Sidebar
        role="Client"
        items={clientNavItems}
        activeItem={showIncharges ? "incharges" : undefined}
        onSelect={handleSidebarSelect}
        onLogout={handleLogout}
      />

      <main className="dashboard-main">
        <Navbar title={currentPage.title} subtitle={currentPage.subtitle} userRole="Client" />

        {message ? <div className="alert info">{message}</div> : null}

        {view === "overview" ? (
          <>
            <section className="summary-grid">
              <div className="metric-card">
                <p>Total Bookings</p>
                <h2>{bookings.length}</h2>
              </div>
              <div className="metric-card metric-card-pending">
                <p>Pending</p>
                <h2>{pendingCount}</h2>
              </div>
              <div className="metric-card metric-card-approved">
                <p>Approved</p>
                <h2>{approvedCount}</h2>
              </div>
              <div className="metric-card metric-card-rejected">
                <p>Rejected</p>
                <h2>{rejectedCount}</h2>
              </div>
            </section>

            <BookingList
              title="Recent Bookings"
              description="Your latest requests and outcomes."
              bookings={recentBookings}
            />
          </>
        ) : null}

        {view === "new-booking" ? (
          <BookingForm
            formData={formData}
            onChange={handleChange}
            onSubmit={handleSubmit}
            onAvailabilityCheck={handleAvailabilityCheck}
            loading={loading}
          />
        ) : null}

        {view === "my-bookings" ? (
          <BookingList
            title="My Bookings"
            description="Rejected requests include the saved reason."
            bookings={bookings}
            onCancel={handleCancel}
            showActions
          />
        ) : null}
      </main>

      <InchargeModal open={showIncharges} groups={inchargeGroups} onClose={() => setShowIncharges(false)} />
    </div>
  );
};

export default ClientDashboard;
